let inputData = $input.first().json;
let rawText = "";

// 1. Grab the text from the exact path Gemini is using in your screenshot
if (inputData.content && inputData.content.parts && inputData.content.parts.length > 0) {
    rawText = inputData.content.parts[0].text;
} else if (inputData.text) {
    rawText = inputData.text; // Fallback
}

// 2. Clean up any markdown codeblocks
rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

// 3. Parse, normalize, and return the clean JSON
try {
    let parsed = JSON.parse(rawText);

    // Ensure every expected field exists so downstream nodes never break
    let result = {
        doctor:     parsed.doctor     || { name: null },
        facility:   parsed.facility   || { name: null },
        diagnosis:  parsed.diagnosis  ?? null,
        medications: Array.isArray(parsed.medications) ? parsed.medications : [],
        lab_results: Array.isArray(parsed.lab_results) ? parsed.lab_results : [],
        scan_report: parsed.scan_report || {
            type: null,
            findings: null,
            impression: null
        },
        confidence: parsed.confidence || { overall: null }
    };

    return { json: result };

} catch(e) {
    return {
        json: {
            doctor: { name: "JSON ERROR" },
            facility: { name: null },
            diagnosis: "Still failed to parse this text: " + rawText,
            medications: [],
            lab_results: [],
            scan_report: { type: null, findings: null, impression: null },
            confidence: { overall: 0 }
        }
    };
}
